insert into public.freight_bands (table_id, band_index, ws, we, amc, pew, pct, max_vol, min_ins)
select t.id, (b->>0)::int, (b->>1)::numeric, (b->>2)::numeric, (b->>3)::numeric, (b->>4)::numeric,
       (b->>5)::numeric, (b->>6)::numeric, (b->>7)::numeric
from data d
join public.stores s on s.name = d.store
join public.freight_tables t on t.store_id = s.id and t.name = 'Tabela de frete (padrão)'
cross join lateral jsonb_array_elements(d.bands) b
where not exists (
  select 1 from public.freight_bands x where x.table_id = t.id and x.band_index = (b->>0)::int
);
